mapper.select:
SELECT c.component_id, c.repository_id, c.namespace, c.name, c.kind, c.version, c.normalized_version, c.attributes, c.created, c.last_updated, c.entity_version, c.base_version, a.asset_id, a.asset_blob_id, b.blob_created FROM maven2_component c LEFT JOIN maven2_asset as a ON c.component_id = a.component_id LEFT JOIN maven2_asset_blob as b ON a.asset_blob_id = b.asset_blob_id WHERE (c.name = #{name} AND c.namespace = #{group}) AND c.repository_id = #{repositoryId} AND (c.base_version = #{baseVersion} OR c.base_version = #{releaseVersion}) AND c.base_version LIKE '%-SNAPSHOT'
AND c.deleted_on IS NULL AND (a.asset_id IS NULL OR a.deleted_on IS NULL)
ORDER BY version DESC;

SELECT maven2_component.component_id FROM maven2_component INNER JOIN maven2_asset ON maven2_component.component_id = maven2_asset.component_id LEFT JOIN maven2_asset_blob ON maven2_asset.asset_blob_id = maven2_asset_blob.asset_blob_id WHERE maven2_component.repository_id = #{repositoryId} AND maven2_component.base_version LIKE '%-SNAPSHOT'
AND maven2_component.deleted_on IS NULL AND maven2_asset.deleted_on IS NULL
GROUP BY maven2_component.component_id HAVING max(coalesce(maven2_asset.last_downloaded, maven2_asset_blob.blob_created)) < #{olderThan} ORDER BY maven2_component.component_id LIMIT #{limit}

SELECT DISTINCT base_version
  FROM maven2_component
 WHERE namespace = #{namespace}
   AND name = #{name}
   AND repository_id = #{repositoryId}
   AND deleted_on IS NULL;
